export var getResults = function(limit, sortKey, isAscending) {
  var bestGroupResult, groupKey, groupResults, results, sortFunction, tmp;
  log("getResults");
  sortFunction = getSortFunction(sortKey, isAscending);
  results = [];
  for (groupKey in groupedResults) {
    groupResults = groupedResults[groupKey];
    groupResults.sort(sortFunction);
    tmp = groupResults.filter(filterResult);
    bestGroupResult = tmp[0];
    if (bestGroupResult != null) {
      results.push(bestGroupResult);
    }
  }
  // each groupd was added independently -> sort    
  results.sort(sortFunction);
  if (limit > results.length) {
    return results;
  }
  return results.slice(0, limit);
};


