export var getTradeResultDetails = async function(tradeKey) {
  var e, evaluation, evnt, evntId, l, len1, ref, result, sym, tkns, trade;
  log("getTradeResultDetails");
  log(tradeKey);
  tkns = tradeKey.split(":");
  if (tkns.length !== 3) {
    throw new Error(`Invalid TradeKey! ${tradeKey}`);
  }
  sym = tkns[0];
  evntId = tkns[1];
  trade = tkns[2];
  evnt = null;
  ref = screeningInputs.eventList;
  for (l = 0, len1 = ref.length; l < len1; l++) {
    e = ref[l];
    if (!(e.id === evntId)) {
      continue;
    }
    evnt = e;
    break;
  }
  if (evnt == null) {
    throw new Error(`Could not find the target Event with id ${evntId}`);
  }
  evaluation = (await evaluateEventTrades(sym, evnt, trade));
  result = generateResultDetailsObject(evaluation, evnt, trade);
  if (result == null) {
    throw new Error(`Could not evaluateEventTrades for ${tradeKey}`);
  }
  return result;
};

