evaluateEventTrades = async function(sym, evnt, trade) {
  var backtester, date, dates, err, key, l, len1, res, runKey, tdc, year;
  try {
    key = `${sym}:${evnt.id}:${trade}`;
    dates = evnt.datesToScreen;
    tdc = getTradeDayConfig();
    backtester = new SymbolBacktester(sym, key, tdc);
    await backtester.loadData();
    for (l = 0, len1 = dates.length; l < len1; l++) {
      date = dates[l];
      year = parseInt(date.slice(0, 4));
      runKey = key + `@${date}`;
      res = getLeapNormIndicesForTrade(date, trade);
      backtester.addBacktestRun(year, res.startIdxLN, res.endIdxLN, runKey);
    }
    return backtester.runEvaluationSync();
  } catch (error) {
    err = error;
    console.error(`@eventscreenerengine.evaluateEventTrades: ${err.message}`);
  }
  return null;
};

