//region general Helper Functions
getTrades14D = function() {
  var i, j, l, m, ref, result;
  //idx 0 = 14th day before
  //idx 28 = 14th day after
  result = [];
  for (i = l = 0; l <= 27; i = ++l) {
    for (j = m = ref = i + 1; (ref <= 28 ? m <= 28 : m >= 28); j = ref <= 28 ? ++m : --m) {
      result.push(`${i}-${j}-14`);
    }
  }
  return result;
};

getTrades4D = function() {
  var i, j, l, m, ref, result;
  //idx 0 = 4th day before
  //idx 8 = 4th day after
  result = [];
  for (i = l = 0; l <= 7; i = ++l) {
    for (j = m = ref = i + 1; (ref <= 8 ? m <= 8 : m >= 8); j = ref <= 8 ? ++m : --m) {
      result.push(`${i}-${j}-4`);
    }
  }
  return result;
};

//###########################################################
getLeapNormIndicesForTrade = function(date, trade) {
  var entrIdx, evntIdx, exitIdx, idxLN, idxR, isLeap, relEntry, relExit, result, tkns, tradeDate;
  tkns = trade.split("-");
  entrIdx = parseInt(tkns[0]);
  exitIdx = parseInt(tkns[1]);
  evntIdx = parseInt(tkns[2]);
  relEntry = entrIdx - evntIdx;
  relExit = exitIdx - evntIdx;
  tradeDate = new Date(date + "T12:00Z");
  isLeap = utl.isLeapYear(tradeDate.getFullYear());
  idxR = utl.getDayOfYear(tradeDate); // real index of trade date
  idxLN = utl.realToLeapNormIdx(idxR, isLeap); // Leap normed index of trade date
  result = Object.create(null);
  // We need to return Leap Normed Indices for the backtester.addBacktestRun()
  result.startIdxLN = idxLN + relEntry;
  result.endIdxLN = idxLN + relExit;
  return result;
};

//###########################################################
getNextTradeDates = function(trade, evnt) {
  var date, dateObj, dates, effEntry, effExit, entrIdx, entryIdxR, err, evntIdx, exitIdx, exitIdxR, idxR, l, len1, relEntry, relExit, result, targetEntry, targetExit, tkns, todayDate;
  // log "getNextTradeDates"

  //# TODO introduce options to adjust behaviour...
  //    - case 0: neither exit nor entry date is a weekend -> next date in future
  //    - case 1: either exit or entry is on a weekend
  //    - case 1.a: trade becomes non-tradable -> next date
  //    - case 1.b: filter is set with mintraduduration and it falls short -> next date?
  //    - case 1.c: filter is set to ignore dates that fall on Weekends -> next date 
  tkns = trade.split("-");
  entrIdx = parseInt(tkns[0]);
  exitIdx = parseInt(tkns[1]);
  evntIdx = parseInt(tkns[2]);
  relEntry = entrIdx - evntIdx;
  relExit = exitIdx - evntIdx;
  result = Object.create(null);
  try {
    // olog evnt.nextDates
    dates = evnt.nextDates;
    todayDate = (new Date()).toISOString().slice(0, 10);
// dates are YYYY-MM-DD strings
    for (l = 0, len1 = dates.length; l < len1; l++) {
      date = dates[l];
      dateObj = new Date(date + "T12:00Z");
      idxR = utl.getDayOfYear(dateObj);
      entryIdxR = idxR + relEntry;
      exitIdxR = idxR + relExit;
      targetEntry = utl.realIdxToYYYYMMDD(dateObj.getFullYear(), entryIdxR);
      targetExit = utl.realIdxToYYYYMMDD(dateObj.getFullYear(), exitIdxR);
      effEntry = utl.nextWeekdayAfter(targetEntry);
      effExit = utl.lastWeekdayBefore(targetExit);
      // log "attempt af effEntry: #{effEntry}"
      if (effEntry < todayDate) {
        continue; //# our entry is not in the future
      }
      if (effEntry === effExit || effEntry > effExit) {
        continue; //# not tradable
      }
      
      //# results are also YYYY-MM-DD strings
      result.nextDate = date;
      result.nextEntryDate = effEntry;
      result.nextExitDate = effExit;
      // olog result
      return result;
    }
  } catch (error) {
    err = error;
    log(err);
    olog({trade, dates});
    return result;
  }
  return result;
};

//###########################################################
getAverageDailyReturnSeq = async function(infoObjects, key) {
  var centerIdx, count, cumFactors, dataPerYear, evntDateObj, f, factorsArray, fullLen, i, l, len1, len2, len3, m, metaData, n, obj, rawData, rawEndIdx, rawStartIdx, seq, sum, sums, sym, tkns, trade, zeroDateObj;
  // log "getAverageDailyReturnSeq"
  // log key
  tkns = key.split(":");
  sym = tkns[0];
  trade = tkns[2];
  tkns = trade.split("-");
  centerIdx = parseInt(tkns[2]);
  fullLen = 2 * centerIdx + 1;
  dataPerYear = (await dCache.getHistoryHLC(sym, 31)); //# ensure data is loaded
  rawData = dCache.getCurrentRawData(sym);
  metaData = dCache.getCurrentMetaData(sym);
  zeroDateObj = new Date(metaData.startDate + "T12:00Z");
  count = 0;
  sums = new Array(fullLen - 1).fill(0);
// log zeroDateObj
  for (l = 0, len1 = infoObjects.length; l < len1; l++) {
    obj = infoObjects[l];
    evntDateObj = getCorrespondingDateObj(obj);
    rawStartIdx = utl.dateDifDays(zeroDateObj, evntDateObj) - centerIdx;
    // log rawStartIdx
    rawEndIdx = rawStartIdx + fullLen;
    // do we have all data available for this event?
    if (rawStartIdx < 0 || rawEndIdx >= rawData.length) {
      continue;
    }
    count++; // adding another row of factors
    seq = rawData.slice(rawStartIdx, rawEndIdx);
    factorsArray = utl.toFactorsArray(seq.map(function(el) {
      return el[el.length - 1];
    }));
    if (factorsArray.length !== sums.length) {
      alert("unexpected factorsArray length!");
    }
    for (i = m = 0, len2 = factorsArray.length; m < len2; i = ++m) {
      f = factorsArray[i];
      sums[i] += f;
    }
  }
  cumFactors = [];
  for (n = 0, len3 = sums.length; n < len3; n++) {
    sum = sums[n];
    cumFactors.push(sum / count);
  }
  return utl.fromFactorsForward(cumFactors);
};

//###########################################################
getCorrespondingDateObj = function(runObj) {
  var date;
  date = runObj.key.split("@")[1];
  // log date
  return new Date(date + "T12:00Z");
};


