//###########################################################
//region Compare Functions + getSortFunction
numberCompare = function(a, b, f) {
  return (b - a) * f;
};

negNumberCompare = function(a, b, f) {
  return ((-b) - (-a)) * f;
};

stringCompare = function(a, b, f) {
  if (a > b) {
    return (-1) * f;
  }
  if (a < b) {
    return f;
  }
  return 0;
};

//###########################################################
getSortFunction = function(sortKey, isAscending) {
  var f, info;
  log(`getSortFunction ${sortKey}, ${isAscending}`);
  info = keyToInfo[sortKey];
  if (isAscending) {
    f = -1;
  } else {
    f = 1;
  }
  switch (sortKey) {
    case "symbol":
      return function(el1, el2) {
        return stringCompare(el1.symbol, el2.symbol, f);
      };
    case "marketcap":
      return function(el1, el2) {
        return numberCompare(el1.marketcap, el2.marketcap, f);
      };
    case "eventLabel":
      return function(el1, el2) {
        return stringCompare(el1.eventLabel, el2.eventLabel, f);
      };
    case "direction":
      return function(el1, el2) {
        return stringCompare(el1.direction, el2.direction, f);
      };
    case "winrate":
      return function(el1, el2) {
        return numberCompare(el1.winrate, el2.winrate, f);
      };
    case "profitAvg":
      return function(el1, el2) {
        return numberCompare(el1.profitAvg, el2.profitAvg, f);
      };
    case "profitMed":
      return function(el1, el2) {
        return numberCompare(el1.profitMed, el2.profitMed, f);
      };
    case "maxRise":
      return function(el1, el2) {
        return numberCompare(el1.maxRise, el2.maxRise, f);
      };
    case "maxDrop":
      return function(el1, el2) {
        return negNumberCompare(el1.maxDrop, el2.maxDrop, f);
      };
    case "nextDate":
      return function(el1, el2) {
        return stringCompare(el1.nextDate, el2.nextDate, f);
      };
    case "entryDate":
      return function(el1, el2) {
        return stringCompare(el1.entryDate, el2.entryDate, f);
      };
    case "exitDate":
      return function(el1, el2) {
        return stringCompare(el1.nextDate, el2.exitDate, f);
      };
    default:
      throw new Error(`No sort Function for ${sortKey}!`);
  }
};


